    ...firstConnection.headers,
  };
  const updatedFromFirstContext =
    await api.functional.erpHrmTime.member.profile.update(firstConnection, {
      body: {
        displayName: firstUpdatedDisplayName,
        avatarImageUrl,
        phoneNumber,
      } satisfies IErpHrmTimeMember.IUpdate,
