    membership.createdAt.length > 0,
  );
  TestValidator.predicate(
    "membership should expose updated timestamp",
    membership.updatedAt.length > 0,
  );
  TestValidator.predicate(
    "membership should not expose role assignment fields",
    !("role" in membership) &&
